#include <array>
#include <iostream>
#include <thread>
#include <vector>
int main() {
    std::array<int,3> results{};
    {
        std::vector<std::jthread> workers;
        workers.reserve(3);
        for (int id = 0; id < 3; ++id)
            workers.emplace_back([id, &results] { results[id] = 10 + id; });
    } // Every jthread has joined before results are read.
    std::cout << results[0] << ' ' << results[1] << ' ' << results[2] << '\n';
}

#include <exception>
#include <iostream>
#include <stdexcept>
#include <thread>
int main() {
    std::exception_ptr failure;
    std::jthread worker([&failure] {
        try { throw std::runtime_error("bad sample"); }
        catch (...) { failure = std::current_exception(); }
    });
    worker.join();
    try {
        if (failure) std::rethrow_exception(failure);
    } catch (const std::exception& error) {
        std::cout << "caught: " << error.what() << '\n';
    }
}

